"use client";

import { useState } from 'react';

const QuoteWidget = ({ actionProvider, setState, state }) => {
  const [step, setStep] = useState(1);
  const [formData, setFormData] = useState({
    weight: '',
    length: '',
    width: '',
    height: '',
    origin: '',
    destination: '',
    speed: 'standard'
  });
  const [quote, setQuote] = useState(null);
  const [loading, setLoading] = useState(false);

  const handleNext = () => {
    if (step < 3) setStep(step + 1);
  };

  const handleBack = () => {
    if (step > 1) setStep(step - 1);
  };

  const handleSubmit = async () => {
    setLoading(true);
    
    setTimeout(() => {
      const baseRate = Math.random() * 50 + 20;
      const fuel = baseRate * 0.15;
      const duties = baseRate * 0.12;
      const vat = (baseRate + duties) * 0.20;
      const total = baseRate + fuel + duties + vat;
      
      setQuote({
        baseRate: baseRate.toFixed(2),
        fuel: fuel.toFixed(2),
        duties: duties.toFixed(2),
        vat: vat.toFixed(2),
        total: total.toFixed(2)
      });
      setLoading(false);
    }, 1500);
  };

  const isStepValid = () => {
    if (step === 1) return formData.weight && formData.length && formData.width && formData.height;
    if (step === 2) return formData.origin && formData.destination;
    return true;
  };

  if (quote) {
    return (
      <div className="bg-gradient-to-br from-white to-blue-50 rounded-2xl border border-blue-100 p-5 mt-4 max-w-sm shadow-lg">
        <div className="text-center">
          <div className="w-12 h-12 bg-gradient-to-r from-blue-500 to-blue-600 rounded-full flex items-center justify-center text-white text-xl mb-3 mx-auto">
            📦
          </div>
          <h3 className="font-bold text-gray-900 mb-1 text-lg">Your Quote</h3>
          <p className="text-sm text-gray-600 mb-4">From {formData.origin} to {formData.destination}</p>
          
          <div className="bg-gradient-to-r from-blue-600 to-indigo-600 rounded-xl p-4 mb-4 text-white">
            <div className="text-3xl font-bold mb-1">£{quote.total}</div>
            <p className="text-blue-100 text-sm">Total cost including all fees</p>
          </div>

          <div className="bg-white rounded-xl p-4 space-y-3 text-left text-sm mb-4 border border-gray-100">
            <div className="flex justify-between items-center">
              <span className="text-gray-600">Base shipping</span>
              <span className="font-semibold text-gray-900">£{quote.baseRate}</span>
            </div>
            <div className="flex justify-between items-center">
              <span className="text-gray-600">Fuel surcharge</span>
              <span className="font-semibold text-gray-900">£{quote.fuel}</span>
            </div>
            <div className="flex justify-between items-center">
              <span className="text-gray-600">Import duties</span>
              <span className="font-semibold text-gray-900">£{quote.duties}</span>
            </div>
            <div className="flex justify-between items-center pt-2 border-t border-gray-200">
              <span className="text-gray-600">VAT (20%)</span>
              <span className="font-semibold text-gray-900">£{quote.vat}</span>
            </div>
          </div>

          <div className="flex gap-2">
            <button
              onClick={() => {setQuote(null); setStep(1); setFormData({weight: '', length: '', width: '', height: '', origin: '', destination: '', speed: 'standard'});}}
              className="flex-1 px-4 py-2 border border-gray-300 text-gray-700 text-sm rounded-xl hover:bg-gray-50 transition-colors"
            >
              New Quote
            </button>
            <button className="flex-1 px-4 py-2 bg-gradient-to-r from-blue-600 to-indigo-600 text-white text-sm rounded-xl hover:from-blue-700 hover:to-indigo-700 transition-all transform hover:scale-105">
              Book Now
            </button>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="bg-gradient-to-br from-white to-gray-50 rounded-2xl border border-gray-200 p-5 mt-4 max-w-sm shadow-lg">
      {/* Enhanced Progress indicator */}
      <div className="flex items-center justify-center mb-6">
        <div className="flex items-center space-x-3">
          {[1, 2, 3].map((i) => (
            <div key={i} className="flex items-center">
              <div className={`w-8 h-8 rounded-full flex items-center justify-center text-xs font-bold transition-all ${
                i <= step 
                  ? 'bg-gradient-to-r from-blue-500 to-blue-600 text-white shadow-md' 
                  : 'bg-gray-200 text-gray-500'
              }`}>
                {i <= step ? '✓' : i}
              </div>
              {i < 3 && <div className={`w-12 h-1 rounded-full transition-all ${i < step ? 'bg-gradient-to-r from-blue-500 to-blue-600' : 'bg-gray-200'}`} />}
            </div>
          ))}
        </div>
      </div>

      <div className="text-center mb-5">
        <h3 className="font-bold text-gray-900 mb-2 text-lg">
          {step === 1 && "📦 Package Details"}
          {step === 2 && "🌍 Shipping Route"}
          {step === 3 && "⚡ Service Speed"}
        </h3>
        <p className="text-sm text-gray-600">
          {step === 1 && "Enter your package dimensions"}
          {step === 2 && "Where are you shipping?"}
          {step === 3 && "Choose delivery speed"}
        </p>
      </div>

      {/* Step 1: Package Details */}
      {step === 1 && (
        <div className="space-y-4">
          <div className="grid grid-cols-2 gap-3">
            <div>
              <label className="block text-xs font-semibold text-gray-700 mb-2">Weight (kg)</label>
              <input
                type="number"
                placeholder="2.5"
                className="w-full border-2 border-gray-200 rounded-xl px-3 py-3 text-sm text-gray-900 focus:border-blue-500 focus:ring-0 transition-colors bg-white"
                value={formData.weight}
                onChange={(e) => setFormData({...formData, weight: e.target.value})}
              />
            </div>
            <div>
              <label className="block text-xs font-semibold text-gray-700 mb-2">Length (cm)</label>
              <input
                type="number"
                placeholder="30"
                className="w-full border-2 border-gray-200 rounded-xl px-3 py-3 text-sm text-gray-900 focus:border-blue-500 focus:ring-0 transition-colors bg-white"
                value={formData.length}
                onChange={(e) => setFormData({...formData, length: e.target.value})}
              />
            </div>
            <div>
              <label className="block text-xs font-semibold text-gray-700 mb-2">Width (cm)</label>
              <input
                type="number"
                placeholder="20"
                className="w-full border-2 border-gray-200 rounded-xl px-3 py-3 text-sm text-gray-900 focus:border-blue-500 focus:ring-0 transition-colors bg-white"
                value={formData.width}
                onChange={(e) => setFormData({...formData, width: e.target.value})}
              />
            </div>
            <div>
              <label className="block text-xs font-semibold text-gray-700 mb-2">Height (cm)</label>
              <input
                type="number"
                placeholder="15"
                className="w-full border-2 border-gray-200 rounded-xl px-3 py-3 text-sm text-gray-900 focus:border-blue-500 focus:ring-0 transition-colors bg-white"
                value={formData.height}
                onChange={(e) => setFormData({...formData, height: e.target.value})}
              />
            </div>
          </div>
        </div>
      )}

      {/* Step 2: Origin and Destination */}
      {step === 2 && (
        <div className="space-y-4">
          <div>
            <label className="block text-xs font-semibold text-gray-700 mb-2">Ship from</label>
            <input
              type="text"
              placeholder="New York, United States"
              className="w-full border-2 border-gray-200 rounded-xl px-4 py-3 text-sm text-gray-900 focus:border-blue-500 focus:ring-0 transition-colors bg-white"
              value={formData.origin}
              onChange={(e) => setFormData({...formData, origin: e.target.value})}
            />
          </div>
          <div>
            <label className="block text-xs font-semibold text-gray-700 mb-2">Ship to</label>
            <input
              type="text"
              placeholder="London, United Kingdom"
              className="w-full border-2 border-gray-200 rounded-xl px-4 py-3 text-sm text-gray-900 focus:border-blue-500 focus:ring-0 transition-colors bg-white"
              value={formData.destination}
              onChange={(e) => setFormData({...formData, destination: e.target.value})}
            />
          </div>
        </div>
      )}

      {/* Step 3: Shipping Speed */}
      {step === 3 && (
        <div className="space-y-3">
          {[
            { value: "standard", name: "Standard", time: "5-7 days", icon: "🚛", color: "blue" },
            { value: "express", name: "Express", time: "2-3 days", icon: "✈️", color: "green" },
            { value: "overnight", name: "Overnight", time: "Next day", icon: "⚡", color: "purple" }
          ].map((option) => (
            <label key={option.value} className="block cursor-pointer group">
              <input
                type="radio"
                name="speed"
                value={option.value}
                checked={formData.speed === option.value}
                onChange={(e) => setFormData({...formData, speed: e.target.value})}
                className="sr-only"
              />
              <div className={`border-2 rounded-xl p-4 transition-all group-hover:shadow-md ${
                formData.speed === option.value 
                  ? `border-${option.color}-500 bg-${option.color}-50 shadow-md` 
                  : 'border-gray-200 hover:border-gray-300 bg-white'
              }`}>
                <div className="flex items-center justify-between">
                  <div className="flex items-center space-x-3">
                    <span className="text-xl">{option.icon}</span>
                    <div>
                      <div className="font-semibold text-gray-900">{option.name}</div>
                      <div className="text-sm text-gray-600">{option.time}</div>
                    </div>
                  </div>
                  {formData.speed === option.value && (
                    <div className="w-5 h-5 bg-blue-500 rounded-full flex items-center justify-center">
                      <svg className="w-3 h-3 text-white" fill="currentColor" viewBox="0 0 20 20">
                        <path fillRule="evenodd" d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z" clipRule="evenodd" />
                      </svg>
                    </div>
                  )}
                </div>
              </div>
            </label>
          ))}
        </div>
      )}

      {/* Enhanced Navigation buttons */}
      <div className="flex justify-between mt-6">
        <button
          onClick={handleBack}
          disabled={step === 1}
          className="px-5 py-2 text-sm text-gray-600 disabled:opacity-50 disabled:cursor-not-allowed hover:text-gray-800 transition-colors flex items-center space-x-1"
        >
          <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" />
          </svg>
          <span>Back</span>
        </button>
        {step < 3 ? (
          <button
            onClick={handleNext}
            disabled={!isStepValid()}
            className="px-6 py-2 bg-gradient-to-r from-blue-600 to-indigo-600 text-white text-sm rounded-xl hover:from-blue-700 hover:to-indigo-700 disabled:opacity-50 disabled:cursor-not-allowed transition-all transform hover:scale-105 flex items-center space-x-1"
          >
            <span>Continue</span>
            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" />
            </svg>
          </button>
        ) : (
          <button
            onClick={handleSubmit}
            disabled={loading}
            className="px-6 py-2 bg-gradient-to-r from-blue-600 to-indigo-600 text-white text-sm rounded-xl hover:from-blue-700 hover:to-indigo-700 disabled:opacity-50 transition-all transform hover:scale-105 flex items-center space-x-2"
          >
            {loading && (
              <svg className="animate-spin w-4 h-4" fill="none" viewBox="0 0 24 24">
                <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
              </svg>
            )}
            <span>{loading ? "Calculating..." : "Get Quote"}</span>
          </button>
        )}
      </div>
    </div>
  );
};

export default QuoteWidget; 