"use client";

import { useState } from 'react';

const TrackingWidget = ({ actionProvider, setState, state }) => {
  const [trackingNumber, setTrackingNumber] = useState('');
  const [trackingResult, setTrackingResult] = useState(null);
  const [loading, setLoading] = useState(false);

  const handleTrack = async (e) => {
    e.preventDefault();
    if (!trackingNumber.trim()) return;
    
    setLoading(true);
    
    setTimeout(() => {
      setTrackingResult({
        status: "In Transit",
        location: "Distribution Center - Manchester, UK",
        estimatedDelivery: "Tomorrow by 6:00 PM",
        timeline: [
          { status: "Order Placed", date: "Dec 15, 2:30 PM", completed: true },
          { status: "Package Picked Up", date: "Dec 16, 9:15 AM", completed: true },
          { status: "In Transit", date: "Dec 17, 11:45 AM", completed: true },
          { status: "Out for Delivery", date: "Dec 18, Expected", completed: false },
          { status: "Delivered", date: "Dec 18, Expected", completed: false }
        ]
      });
      setLoading(false);
    }, 1000);
  };

  return (
    <div className="bg-gradient-to-br from-white to-green-50 rounded-2xl border border-green-100 p-5 mt-4 max-w-sm shadow-lg">
      <div className="text-center mb-5">
        <div className="w-12 h-12 bg-gradient-to-r from-green-500 to-green-600 rounded-full flex items-center justify-center text-white text-xl mb-3 mx-auto">
          📍
        </div>
        <h3 className="font-bold text-gray-900 mb-1 text-lg">Track Package</h3>
        <p className="text-sm text-gray-600">Enter your tracking number below</p>
      </div>

      <form onSubmit={handleTrack} className="mb-5">
        <div className="flex gap-2">
          <input
            type="text"
            placeholder="1Z999AA1234567890"
            className="flex-1 border-2 border-gray-200 rounded-xl px-4 py-3 text-sm text-gray-900 focus:border-green-500 focus:ring-0 transition-colors bg-white"
            value={trackingNumber}
            onChange={(e) => setTrackingNumber(e.target.value)}
          />
          <button
            type="submit"
            disabled={loading || !trackingNumber.trim()}
            className="px-5 py-3 bg-gradient-to-r from-green-600 to-green-700 text-white text-sm rounded-xl hover:from-green-700 hover:to-green-800 disabled:opacity-50 disabled:cursor-not-allowed transition-all transform hover:scale-105 flex items-center"
          >
            {loading ? (
              <svg className="animate-spin w-4 h-4" fill="none" viewBox="0 0 24 24">
                <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
              </svg>
            ) : (
              <span>Track</span>
            )}
          </button>
        </div>
      </form>

      {trackingResult && (
        <div className="space-y-5">
          <div className="text-center p-4 bg-gradient-to-r from-green-600 to-green-700 rounded-xl text-white">
            <div className="font-bold text-lg mb-1">{trackingResult.status}</div>
            <p className="text-green-100 text-sm mb-1 flex items-center justify-center">
              <svg className="w-4 h-4 mr-1" fill="currentColor" viewBox="0 0 20 20">
                <path fillRule="evenodd" d="M5.05 4.05a7 7 0 119.9 9.9L10 18.9l-4.95-4.95a7 7 0 010-9.9zM10 11a2 2 0 100-4 2 2 0 000 4z" clipRule="evenodd" />
              </svg>
              {trackingResult.location}
            </p>
            <p className="text-xs text-green-200">Expected: {trackingResult.estimatedDelivery}</p>
          </div>
          
          <div className="bg-white rounded-xl p-4 border border-gray-100">
            <h4 className="font-semibold text-gray-900 text-sm mb-4 flex items-center">
              <svg className="w-4 h-4 mr-2 text-gray-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" />
              </svg>
              Timeline
            </h4>
            <div className="space-y-4">
              {trackingResult.timeline.map((event, index) => (
                <div key={index} className="flex items-start space-x-3">
                  <div className={`w-4 h-4 rounded-full mt-0.5 flex-shrink-0 transition-all ${
                    event.completed 
                      ? 'bg-gradient-to-r from-green-500 to-green-600 shadow-md' 
                      : 'bg-gray-300'
                  }`}>
                    {event.completed && (
                      <svg className="w-4 h-4 text-white" fill="currentColor" viewBox="0 0 20 20">
                        <path fillRule="evenodd" d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z" clipRule="evenodd" />
                      </svg>
                    )}
                  </div>
                  <div className="flex-1 min-w-0">
                    <div className={`text-sm font-medium transition-colors ${
                      event.completed ? 'text-gray-900' : 'text-gray-500'
                    }`}>
                      {event.status}
                    </div>
                    <div className={`text-xs transition-colors ${
                      event.completed ? 'text-gray-600' : 'text-gray-400'
                    }`}>
                      {event.date}
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </div>
          
          <button
            onClick={() => {setTrackingResult(null); setTrackingNumber('');}}
            className="w-full px-4 py-3 text-sm text-gray-600 border-2 border-gray-200 rounded-xl hover:bg-gray-50 hover:border-gray-300 transition-all transform hover:scale-105 flex items-center justify-center space-x-2"
          >
            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15" />
            </svg>
            <span>Track Another Package</span>
          </button>
        </div>
      )}
    </div>
  );
};

export default TrackingWidget; 